from collections import Counter
from urban_micro.uhi import _pareto_bootstrap_p_value

def block_quantile(index, n, r):
    rem = index
    for k in range(n+1):
        mult = math.comb(n,k)*r**k*(n-r)**(n-k)
        if rem < mult:
            return k/n
        rem -= mult

def quant_indices(n, conf):
    N=n**n; a=(1-conf)/2
    return math.floor((N-1)*a), math.ceil((N-1)*(1-a))

# literal enumeration n<=6
