            vals=sorted(sum(obs[d]=="W" for d in s)/n
                        for s in itertools.product(range(n),repeat=n))
            li,ui=quant_indices(n,conf)
            assert block_quantile(li,n,r)==vals[li],(n,r,conf)
            assert block_quantile(ui,n,r)==vals[ui],(n,r,conf)
